mapper.select:
select u.real_name, g.grade_name, ues.user_score as score
from t_user_exams_score as ues
join t_user as u on ues.user_id = u.id
join t_user_grade as userGrade on userGrade.u_id = u.id
    and userGrade.g_id = #{gradeId}
    and (userGrade.is_deleted = 0 or userGrade.is_deleted is null)
join t_grade as g on g.id = #{gradeId}
where ues.exam_id = #{examId}
and ues.state = 1
and g.id = #{gradeId}
order by ues.user_score desc;
